"  /* per task: \"hellaswag 27.95  arc_easy 35.86 ...\" in each row's scores */\n"
"  const sc=rows.map(r=>{const o={};for(const m of (r.scores||\"\").matchAll(/([A-Za-z][\\w-]*)\\s+(-?\\d+(?:\\.\\d+)?)/g))o[m[1]]=+m[2];return o});\n"
"  const names=[];sc.forEach(o=>Object.keys(o).forEach(k=>{if(!names.includes(k))names.push(k)}));\n"
"  $(\"tasks\").innerHTML=names.map((k,j)=>`<div><div class=\"tn\"><span>${E(TASK[k]?TASK[k][0]:k)}</span><span id=\"tv${j}\"></span></div><div class=\"ch\" id=\"tc${j}\"></div></div>`).join(\"\")||'<div class=\"empty\">No per-task scores yet</div>';\n"
"  names.forEach((k,j)=>{const d=rows.map((r,i)=>[r.iter,sc[i][k]]).filter(p=>p[1]!=null),m=mean4(d),last=d[d.length-1],ch=TASK[k]?TASK[k][1]:null;\n"
"    $(\"tv\"+j).innerHTML=last?`<b>${last[1].toFixed(1)}%</b> \302\267 mean4 ${m[m.length-1][1].toFixed(1)}${ch!=null?\" \302\267 chance \"+ch:\"\"}`:\"\";\n"
"    chart($(\"tc\"+j),{dots:d,line:m,ref:ch,h:150,label:(TASK[k]?TASK[k][0]:k)+\" accuracy by iteration\",yf:y=>y.toFixed(0),\n"
"      tip:(q,i)=>`iter <b>${n0(q[0])}</b> \302\267 <b>${q[1].toFixed(2)}%</b> \302\267 mean4 ${m[i][1].toFixed(2)}`})});\n"
"  $(\"bta\").innerHTML=rows.length?`<table><tr><th>iter</th><th>II</th><th>margin</th>${names.map(k=>`<th>${E(TASK[k]?TASK[k][0]:k)}</th>`).join(\"\")}</tr>`\n"
"    +rows.map((r,i)=>`<tr><td>${n0(r.iter)}</td><td>${f(r.ii,2)}</td><td>${f(r.margin,3)}</td>${names.map(k=>`<td>${f(sc[i][k],2)}</td>`).join(\"\")}</tr>`).reverse().join(\"\")+\"</table>\":'<div class=\"empty\">No benches yet</div>'}\n"
"const TASK={hellaswag:[\"HellaSwag\",25],arc_easy:[\"ARC-Easy\",25],arc_challenge:[\"ARC-Challenge\",25],piqa:[\"PIQA\",50],lambada:[\"LAMBADA\",0],arithmark:[\"ArithMark\",25],\n"
"  winogrande:[\"WinoGrande\",50],openbookqa:[\"OpenBookQA\",25],boolq:[\"BoolQ\",50],mmlu:[\"MMLU\",25]};\n"
"const mean4=d=>d.map((p,i)=>{const w=d.slice(Math.max(0,i-3),i+1);return[p[0],w.reduce((a,b)=>a+b[1],0)/w.length]});\n"
"$(\"lr\").innerHTML=[[1,\"All\"],[0.5,\"Last half\"],[0.1,\"Last 10%\"]].map(([v,l])=>`<button class=\"chip\" data-r=\"${v}\" aria-pressed=\"false\">${l}</button>`).join(\"\");\n"
"$(\"lr\").onclick=e=>{const b=e.target.closest(\"button\");if(!b)return;range=+b.dataset.r;store(\"cudalm_range\",range);mark();drawLoss();tick()};\n"
"const mark=()=>$(\"lr\").querySelectorAll(\"button\").forEach(b=>{const on=+b.dataset.r==range;b.classList.toggle(\"on\",on);b.setAttribute(\"aria-pressed\",on)});mark();\n"
"$(\"runs\").onclick=e=>{const b=e.target.closest(\".run\");if(!b)return;sel=b.dataset.n;store(\"cudalm_sel\",sel);cache={};tick()};\n"
"$(\"resl\").onclick=e=>{const b=e.target.closest(\"button\");if(!b)return;selRes=b.dataset.n;tick()};\n"
"let busy=false;\n"
"async function tick(){if(busy)return;busy=true;try{\n"
"  const [runs,sys,res]=await Promise.all([api(\"/api/runs\"),api(\"/api/sys\"),api(\"/api/res\")]);\n"
"  const g=(sys.gpus||[])[0];$(\"gpu\").innerHTML=g?`<b>${E(g.name)}</b> \302\267 ${g.util}% busy \302\267 ${f(g.mem_used_mb/1024,1)} / ${f(g.mem_total_mb/1024,1)} GB \302\267 ${g.temp_c} \302\260C \302\267 ${f(g.power_w,0)} W`+(g.fan!=null?` \302\267 fan ${g.fan}%`:\"\")+(sys.disk_free_gb!=null?` \302\267 disk ${f(sys.disk_free_gb,0)} GB free`:\"\"):\"No NVIDIA GPU visible\"+(sys.disk_free_gb!=null?` \302\267 disk ${f(sys.disk_free_gb,0)} GB free`:\"\");\n"
"  $(\"upd\").textContent=\"updated \"+new Date().toLocaleTimeString(\"en-GB\");\n"
"  const R=runs.runs||[];if(!R.find(r=>r.name==sel))sel=((R.find(live)||R[0])||{}).name||null;\n"
"  $(\"runs\").innerHTML=R.length?R.map(runCard).join(\"\"):'<div class=\"card empty\">No runs in the last 14 days</div>';\n"
"  const rs=(res.res||[]).sort((a,b)=>a.age_s-b.age_s).slice(0,8);if(!rs.find(r=>r.name==selRes))selRes=rs.length?rs[0].name:null;\n"
"  $(\"resl\").innerHTML=rs.map(r=>`<button class=\"chip${r.name==selRes?\" on\":\"\"}\" data-n=\"${E(r.name)}\" aria-pressed=\"${r.name==selRes}\">${E(r.name)} <span class=\"sub\">${dur(r.age_s)}</span></button>`).join(\"\")||'<span class=\"empty\">No .res files</span>';\n"
"  if(selRes){const t=await api(\"/api/res/\"+encodeURIComponent(selRes)+\"?tail=30\");const q=$(\"rest\");q.textContent=(t.lines||[]).join(\"\\n\");q.scrollTop=q.scrollHeight}\n"
"  if(sel){const n=encodeURIComponent(sel);const[r,l,b,lg]=await Promise.all([api(\"/api/run/\"+n),api(\"/api/loss/\"+n+\"?pts=\"+Math.round(Math.max(150,Math.min(4000,($(\"lc\").clientWidth||600)/(range>=1?1.5:range>=.5?.75:.15))))),api(\"/api/bench/\"+n),api(\"/api/log/\"+n+\"?tail=60\")]);\n"
"    cache={loss:l,bench:b};$(\"det\").hidden=false;$(\"tiles\").innerHTML=tiles(r);$(\"lt\").textContent=\"Training loss \302\267 \"+sel;\n"
"    document.title=`${(STATE[r.state]||[,,r.state])[2]} \302\267 ${sel} \302\267 cudalm`;drawLoss();drawBench();\n"
"    $(\"lp\").textContent=lg.log||\"no log\";const pre=$(\"log\"),end=pre.scrollTop+pre.clientHeight>=pre.scrollHeight-8;pre.textContent=(lg.lines||[]).join(\"\\n\");if(end)pre.scrollTop=pre.scrollHeight}\n"
"  else $(\"det\").hidden=true;\n"
"}catch(e){if(e.message!=\"token\")$(\"upd\").innerHTML=`<span class=\"err\">${E(e.message)}</span>`}finally{busy=false}}\n"
"let rz;addEventListener(\"resize\",()=>{clearTimeout(rz);rz=setTimeout(()=>{drawLoss();drawBench()},150)});\n"
"tick();setInterval(tick,15000);\n"
"</script>\n"
"</body>\n"
"</html>\n";
